<script setup lang="ts">
import { ArrowUpRight, X } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const api = useApi()
const { data: jobs, refresh } = await useAsyncData('contractor-opportunities', () => api.request<any[]>('/portal/contractor/opportunities').catch(() => []))
const { data: profile, refresh: profileRefresh } = await useAsyncData('contractor-profile', () => api.request<any>('/portal/contractor/profile').catch(() => null))
const { data: workOrders, refresh: woRefresh } = await useAsyncData('contractor-work-orders', () => api.request<any[]>('/portal/contractor/work-orders').catch(() => []))
const profileForm = reactive({ licenseNumber: '', insuranceProvider: '', serviceAreas: '', capabilities: '' })
watch(profile, (v) => { if (v?.profile) { profileForm.licenseNumber = v.profile.licenseNumber || ''; profileForm.insuranceProvider = v.profile.insuranceProvider || ''; profileForm.serviceAreas = (v.profile.serviceAreas || []).join(', '); profileForm.capabilities = (v.profile.capabilities || []).join(', ') } }, { immediate: true })
async function saveProfile() { await api.request('/portal/contractor/profile', { method: 'POST', body: { ...profileForm, serviceAreas: profileForm.serviceAreas.split(',').map(s => s.trim()).filter(Boolean), capabilities: profileForm.capabilities.split(',').map(s => s.trim()).filter(Boolean) } }); await profileRefresh() }
async function complete(id: string) { const notes = window.prompt('Completion notes:') || ''; const photos = window.prompt('Photo URLs (comma separated, optional):') || ''; await api.request(`/portal/work-orders/${id}/complete`, { method: 'POST', body: { notes, photos: photos.split(',').map(s => s.trim()).filter(Boolean) } }); await woRefresh() }
const active = ref<any>(null); const saving = ref(false); const form = reactive({ amountUsd: 0, days: 2, note: '' })
function openBid(job: any) { active.value = job; form.amountUsd = 4800; form.days = 2; form.note = '' }
async function submit() { if (!active.value) return; saving.value = true; try { await api.request(`/portal/jobs/${active.value._id}/bids`, { method: 'POST', body: form }); active.value = null; await refresh() } finally { saving.value = false } }
</script>
<template>
  <div><PortalHeader><template #eyebrow>Contractor network</template><template #title>Scoped work.</template><template #subtitle>Homeowner jobs with camera findings, a repair scope and escrow already funded.</template></PortalHeader>
    <div class="mb-4 grid gap-3 md:grid-cols-2"><div class="rounded-xl border border-ink/12 bg-bone p-4"><div class="flex items-center justify-between"><p class="font-display text-[18px]">Contractor profile</p><StatusPill :status="profile?.profile?.verificationStatus || 'pending'"/></div><div class="mt-3 grid gap-2 sm:grid-cols-2"><input v-model="profileForm.licenseNumber" class="field" placeholder="License number"><input v-model="profileForm.insuranceProvider" class="field" placeholder="Insurance provider"><input v-model="profileForm.serviceAreas" class="field" placeholder="Service areas (comma separated)"><input v-model="profileForm.capabilities" class="field" placeholder="Capabilities"></div><button class="btn btn-outline mt-3 !min-h-8 !text-[9px]" @click="saveProfile">Save & submit verification</button></div><div class="rounded-xl border border-ink/12 bg-bone p-4"><div class="flex items-center justify-between"><p class="font-display text-[18px]">Work orders</p><span class="font-mono text-[8px] text-ink/75">{{ workOrders?.length || 0 }}</span></div><div class="mt-2 divide-y divide-ink/10"><div v-for="wo in workOrders" :key="wo._id" class="flex items-center gap-2 py-2"><div class="min-w-0 flex-1"><p class="truncate text-[11px]">{{ wo.scope }}</p><p class="font-mono text-[7.5px] uppercase text-ink/75">{{ shortDate(wo.scheduledAt) }} · {{ wo.status }}</p></div><button v-if="wo.status !== 'completed' && wo.status !== 'verified'" class="font-mono text-[8px] uppercase text-mint-deep" @click="complete(wo._id)">Complete</button></div></div></div></div><div class="grid gap-4 lg:grid-cols-2"><div v-for="j in jobs" :key="j._id" class="rounded-xl border border-ink/12 bg-bone p-5"><div class="flex items-start justify-between"><div><p class="font-mono text-[8px] uppercase tracking-[.08em] text-ink/75">{{ j.ref }}</p><h3 class="mt-1 font-display text-[23px] tracking-[-.03em]">{{ j.address }}</h3><p class="text-[11.5px] text-ink/75">{{ j.city }} · {{ j.issue }}</p></div><StatusPill :status="j.status" /></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="d in j.defects" :key="d.type" class="rounded-full bg-ink/5 px-2.5 py-1 font-mono text-[8px] uppercase tracking-[.06em] text-ink/75">{{ d.type }} · {{ d.severity }}</span></div><div class="mt-5 flex items-center justify-between border-t border-ink/10 pt-4"><p class="font-mono text-[9px] text-ink/75">{{ j.defects?.length || 0 }} findings · health {{ j.healthScore }}</p><button class="btn btn-dark !min-h-8 !px-3 !text-[9px]" @click="openBid(j)">Submit bid <ArrowUpRight :size="11" /></button></div></div></div>
    <div v-if="!jobs?.length" class="rounded-xl border border-dashed border-ink/20 p-10 text-center text-[13px] text-ink/75">No open opportunities right now.</div>
    <div v-if="active" class="fixed inset-0 z-[70] flex items-center justify-center bg-ink/45 p-4 backdrop-blur-sm" @click.self="active = null"><div class="w-full max-w-md rounded-2xl bg-bone p-6"><div class="flex items-start justify-between"><div><p class="label-mono text-signal-deep">Bid on job</p><h2 class="mt-1 font-display text-[25px]">{{ active.address }}</h2></div><button @click="active = null"><X :size="18" /></button></div><form class="mt-5 space-y-4" @submit.prevent="submit"><div class="grid grid-cols-2 gap-3"><div><label class="field-label">Your price (USD)</label><input v-model.number="form.amountUsd" type="number" required class="field"></div><div><label class="field-label">Days</label><input v-model.number="form.days" type="number" class="field"></div></div><div><label class="field-label">Scope / note</label><textarea v-model="form.note" rows="3" class="field resize-none" placeholder="What is included, exclusions, warranty." /></div><div class="flex justify-end gap-2"><button type="button" class="btn btn-outline" @click="active = null">Cancel</button><button class="btn btn-dark" :disabled="saving">{{ saving ? 'Sending…' : 'Submit bid' }}</button></div></form></div></div>
  </div>
</template>
